//! Component patterns and mirrored components: instances placed by a
//! feature rather than by mates.

use std::f64::consts::TAU;
use std::path::Path;

use of_mate::{DQuat, DVec3, Pose};
use of_model::{FeatureKind, MirrorDef, Ref};

use crate::assembly::{Assembly, Instance, Loaded, resolve_file};
use crate::document::{MirrorComponents, MirrorPosition, Pattern, PatternKind};
use crate::geometry::{self, Geo};

/// Instances generated by one pattern or mirror feature.
pub struct Derived {
    pub id: u32,
    pub instances: Vec<Instance>,
}

/// Rotation by `angle` about the axis through `origin` along `dir`.
pub fn rotation_about(origin: DVec3, dir: DVec3, angle: f64) -> Pose {
    let q = DQuat::from_axis_angle(dir.normalize(), angle);
    Pose::new(origin - q * origin, q)
}

/// Reflection matrix as a function on vectors.
fn reflect(v: DVec3, n: DVec3) -> DVec3 {
    v - n * (2.0 * v.dot(n))
}

/// Copy a seed instance (and, for subassemblies, its children) through a
/// world transform under a new key.
fn copies(
    base: &[Instance],
    seed: &str,
    key: &str,
    t: &Pose,
    id: u32,
    label: &str,
) -> Vec<Instance> {
    base.iter()
        .filter(|i| i.key.first().is_some_and(|k| k == seed) && i.derived.is_none())
        .map(|i| {
            let mut c = i.clone();
            c.key[0] = key.to_string();
            c.pose = t.then(&i.pose);
            if c.key.len() == 1 {
                c.name = format!("{} {label}", i.name);
            }
            c.fixed = true;
            c.derived = Some(id);
            c
        })
        .collect()
}

fn direction(asm: &mut Assembly, r: &crate::CompRef) -> Result<DVec3, String> {
    asm.world_geometry(r)?
        .direction()
        .map(|d| d.normalize())
        .ok_or_else(|| "select an edge, axis or flat face for the direction".into())
}

/// World transforms of a pattern's instances, with their indices (seed is 0).
fn transforms(
    asm: &mut Assembly,
    p: &Pattern,
    base: &[Instance],
) -> Result<Vec<(u32, Pose)>, String> {
    let seed_pose = |key: &str| {
        base.iter()
            .find(|i| i.key.len() == 1 && i.key[0] == key)
            .map(|i| i.pose)
            .ok_or_else(|| format!("seed component {key} is missing"))
    };
    let mut out = Vec::new();
    match &p.kind {
        PatternKind::Linear {
            direction1,
            direction2,
        } => {
            let sign = |r: bool| if r { -1.0 } else { 1.0 };
            let d1 = direction(asm, &direction1.reference)? * sign(direction1.reverse);
            let (d2, s2, n2) = match direction2 {
                Some(d) => (
                    direction(asm, &d.reference)? * sign(d.reverse),
                    d.spacing,
                    d.count,
                ),
                None => (DVec3::ZERO, 0.0, 1),
            };
            if direction1.count * n2 < 2 {
                return Err("the pattern needs more than one instance".into());
            }
            for j in 0..n2 {
                for i in 0..direction1.count {
                    if i == 0 && j == 0 {
                        continue;
                    }
                    let v = d1 * (direction1.spacing * i as f64) + d2 * (s2 * j as f64);
                    out.push((i + j * direction1.count, Pose::from_translation(v)));
                }
            }
        }
        PatternKind::Circular {
            axis,
            angle,
            count,
            equal_spacing,
            reverse,
        } => {
            let (origin, mut dir) = asm
                .world_geometry(axis)?
                .axis()
                .ok_or("select an axis, cylindrical face or circular edge")?;
            if *reverse {
                dir = -dir;
            }
            if *count < 2 {
                return Err("the pattern needs at least 2 instances".into());
            }
            let step = if *equal_spacing {
                if (angle - TAU).abs() < 1e-9 {
                    angle / *count as f64
                } else {
                    angle / (*count - 1) as f64
                }
            } else {
                *angle
            };
            for k in 1..*count {
                out.push((k, rotation_about(origin, dir, step * k as f64)));
            }
        }
        PatternKind::PatternDriven { feature } => {
            let inst = base
                .iter()
                .find(|i| i.key == feature.component)
                .ok_or("select a pattern feature in a component")?;
            let part = inst
                .part()
                .ok_or("the pattern feature must be in a part")?
                .clone();
            let Ref::Feature { id } = feature.entity else {
                return Err("select a pattern feature".into());
            };
            let f = part
                .doc()
                .feature(id)
                .ok_or("the pattern feature no longer exists")?;
            let state = part.state();
            let local: Vec<Pose> = match &f.kind {
                FeatureKind::LinearPattern(lp) => {
                    let dir_of = |d: &of_model::PatternDirection| -> Result<DVec3, String> {
                        let v = of_model::resolve(state, &d.reference)?.direction()?;
                        Ok(if d.reverse { -v } else { v })
                    };
                    let d1 = dir_of(&lp.direction1)?;
                    let (d2, s2, n2) = match &lp.direction2 {
                        Some(d) => (dir_of(d)?, d.spacing, d.count),
                        None => (DVec3::ZERO, 0.0, 1),
                    };
                    let mut v = Vec::new();
                    for j in 0..n2 {
                        for i in 0..lp.direction1.count {
                            if i == 0 && j == 0 {
                                continue;
                            }
                            v.push(Pose::from_translation(
                                d1 * (lp.direction1.spacing * i as f64) + d2 * (s2 * j as f64),
                            ));
                        }
                    }
                    v
                }
                FeatureKind::CircularPattern(cp) => {
                    let (origin, mut dir) = of_model::resolve(state, &cp.axis)?.axis()?;
                    if cp.reverse {
                        dir = -dir;
                    }
                    let step = if cp.equal_spacing {
                        if (cp.angle - TAU).abs() < 1e-9 {
                            cp.angle / cp.count as f64
                        } else {
                            cp.angle / (cp.count.max(2) - 1) as f64
                        }
                    } else {
                        cp.angle
                    };
                    (1..cp.count)
                        .map(|k| rotation_about(origin, dir, step * k as f64))
                        .collect()
                }
                _ => return Err("select a linear or circular pattern feature".into()),
            };
            let to_world = inst.pose;
            for (k, t) in local.iter().enumerate() {
                out.push((k as u32 + 1, to_world.then(t).then(&to_world.inverse())));
            }
        }
        PatternKind::SketchDriven { sketch, reference } => {
            let Ref::Feature { id } = sketch.entity else {
                return Err("select a sketch for the pattern".into());
            };
            // Sketch points in the assembly frame: the assembly's own sketch,
            // or a part sketch placed by its component.
            let (state, to_world) = if sketch.component.is_empty() {
                (asm.reference_state().clone(), Pose::IDENTITY)
            } else {
                let inst = base
                    .iter()
                    .find(|i| i.key == sketch.component)
                    .ok_or("the sketch's component is missing")?;
                let part = inst.part().ok_or("the sketch must be in a part")?;
                (part.state().clone(), inst.pose)
            };
            let (plane, sk) = state.sketches.get(&id).ok_or("select a sketch")?;
            let used: Vec<u32> = sk.entities.values().flat_map(|e| e.point_refs()).collect();
            let points: Vec<DVec3> = sk
                .entities
                .iter()
                .filter(|(id, e)| {
                    **id != of_model::sketch::ORIGIN && !e.construction && !used.contains(id)
                })
                .filter_map(|(_, e)| match e.geo {
                    of_model::sketch::Geometry::Point { p } => Some(to_world.point(plane.to_world(p))),
                    _ => None,
                })
                .collect();
            if points.is_empty() {
                return Err("the sketch has no sketch points".into());
            }
            let seed = p.seeds.first().ok_or("select a seed component")?;
            let anchor = match reference {
                Some(r) => asm.world_geometry(r)?.point(),
                None => seed_pose(seed)?.translation,
            };
            // The seed sits at the sketch point nearest its reference;
            // every other point gets an instance offset from it.
            let home = *points
                .iter()
                .min_by(|a, b| a.distance(anchor).total_cmp(&b.distance(anchor)))
                .unwrap();
            let mut k = 0;
            for q in points {
                if q == home {
                    continue;
                }
                k += 1;
                out.push((k, Pose::from_translation(q - home)));
            }
        }
        PatternKind::CurveDriven {
            curve,
            spacing,
            count,
            tangent,
            reverse,
        } => {
            let mut pieces = Vec::new();
            for r in curve {
                pieces.push(match asm.world_geometry(r)? {
                    Geo::Curve { points, .. } => points,
                    Geo::Line {
                        ends: Some((a, b)), ..
                    } => vec![a, b],
                    Geo::Circle {
                        center,
                        normal,
                        radius,
                    } => {
                        let n = normal.normalize();
                        let u = n.any_orthonormal_vector();
                        let v = n.cross(u);
                        (0..=128)
                            .map(|i| {
                                let t = TAU * i as f64 / 128.0;
                                center + (u * t.cos() + v * t.sin()) * radius
                            })
                            .collect()
                    }
                    g => return Err(format!("a curve pattern can't follow a {}", g.name())),
                });
            }
            let (points, closed) = geometry::chain(pieces)?;
            let seed = p.seeds.first().ok_or("select a seed component")?;
            let anchor = seed_pose(seed)?.translation;
            let (start, s0) = nearest(&points, closed, anchor);
            let total = length(&points, closed);
            let t0 = tangent_at(&points, closed, s0);
            for k in 1..*count {
                let s = s0 + spacing * k as f64 * if *reverse { -1.0 } else { 1.0 };
                if !closed && !(0.0..=total + 1e-9).contains(&s) {
                    break;
                }
                let q = at(&points, closed, s);
                let mut t = Pose::from_translation(q - start);
                if *tangent {
                    let t1 = tangent_at(&points, closed, s);
                    let r = DQuat::from_rotation_arc(t0, t1);
                    t = Pose::from_translation(q)
                        .then(&Pose::new(DVec3::ZERO, r))
                        .then(&Pose::from_translation(-start));
                }
                out.push((k, t));
            }
        }
    }
    Ok(out)
}

fn segments(points: &[DVec3], closed: bool) -> Vec<(DVec3, DVec3)> {
    let n = points.len();
    let count = if closed && n > 2 {
        n
    } else {
        n.saturating_sub(1)
    };
    (0..count)
        .map(|i| (points[i], points[(i + 1) % n]))
        .collect()
}

fn length(points: &[DVec3], closed: bool) -> f64 {
    segments(points, closed)
        .iter()
        .map(|(a, b)| a.distance(*b))
        .sum()
}

fn nearest(points: &[DVec3], closed: bool, p: DVec3) -> (DVec3, f64) {
    let mut best = (f64::MAX, points[0], 0.0);
    let mut s = 0.0;
    for (a, b) in segments(points, closed) {
        let ab = b - a;
        let l2 = ab.length_squared();
        let t = if l2 > 0.0 {
            ((p - a).dot(ab) / l2).clamp(0.0, 1.0)
        } else {
            0.0
        };
        let q = a + ab * t;
        if q.distance_squared(p) < best.0 {
            best = (q.distance_squared(p), q, s + l2.sqrt() * t);
        }
        s += l2.sqrt();
    }
    (best.1, best.2)
}

fn at(points: &[DVec3], closed: bool, s: f64) -> DVec3 {
    let total = length(points, closed);
    let mut s = if closed && total > 0.0 {
        s.rem_euclid(total)
    } else {
        s.clamp(0.0, total)
    };
    for (a, b) in segments(points, closed) {
        let l = a.distance(b);
        if s <= l && l > 0.0 {
            return a + (b - a) * (s / l);
        }
        s -= l;
    }
    *points.last().unwrap()
}

fn tangent_at(points: &[DVec3], closed: bool, s: f64) -> DVec3 {
    let total = length(points, closed);
    let mut s = if closed && total > 0.0 {
        s.rem_euclid(total)
    } else {
        s.clamp(0.0, total)
    };
    let segs = segments(points, closed);
    for (a, b) in &segs {
        let l = a.distance(*b);
        if s <= l && l > 0.0 {
            return (*b - *a) / l;
        }
        s -= l;
    }
    segs.last()
        .map_or(DVec3::X, |(a, b)| (*b - *a).normalize_or_zero())
}

pub(crate) fn pattern(
    asm: &mut Assembly,
    p: &Pattern,
    base: &[Instance],
) -> Result<Derived, String> {
    let ts = transforms(asm, p, base)?;
    let mut instances = Vec::new();
    for seed in &p.seeds {
        if !base.iter().any(|i| i.key.len() == 1 && i.key[0] == *seed) {
            return Err(format!("seed component {seed} is missing or suppressed"));
        }
        for (k, t) in &ts {
            if p.skip.contains(k) {
                continue;
            }
            let key = format!("{seed}@p{}.{k}", p.id);
            instances.extend(copies(base, seed, &key, t, p.id, &format!("[{}]", k + 1)));
        }
    }
    Ok(Derived {
        id: p.id,
        instances,
    })
}

/// The point of a part that a mirror keeps in place, in the part frame.
fn anchor(i: &Instance, position: MirrorPosition) -> DVec3 {
    let Some(shape) = i.part().and_then(|p| p.shape()) else {
        return DVec3::ZERO;
    };
    match position {
        MirrorPosition::Origin => DVec3::ZERO,
        MirrorPosition::BoundingBox => shape.bbox().map_or(DVec3::ZERO, |b| b.center()),
        MirrorPosition::CenterOfMass => shape.mass_props().map_or(DVec3::ZERO, |m| m.center),
    }
}

pub(crate) fn mirror(
    asm: &mut Assembly,
    m: &MirrorComponents,
    base: &[Instance],
) -> Result<Derived, String> {
    let (o, n) = match asm.world_geometry(&m.plane)? {
        Geo::Plane { origin, normal, .. } => (origin, normal.normalize()),
        _ => return Err("select a plane or flat face to mirror about".into()),
    };
    let dir = asm.base_dir();
    let mut instances = Vec::new();
    for item in &m.components {
        let seed = base
            .iter()
            .find(|i| i.key.len() == 1 && i.key[0] == item.component)
            .ok_or_else(|| format!("component {} is missing or suppressed", item.component))?
            .clone();
        let key = format!("{}@m{}", item.component, m.id);
        // Reflection M; for instance copies the orientation M R M is a proper
        // rotation that mirrors symmetric parts correctly.
        let rot = DQuat::from_mat3(&{
            let r = of_mate::DMat3::from_quat(seed.pose.rotation);
            let mm = of_mate::DMat3::from_cols(
                reflect(DVec3::X, n),
                reflect(DVec3::Y, n),
                reflect(DVec3::Z, n),
            );
            match &item.opposite_hand {
                // Opposite-hand parts are already mirrored in X.
                Some(_) => mm * r * of_mate::DMat3::from_diagonal(DVec3::new(-1.0, 1.0, 1.0)),
                None => mm * r * mm,
            }
        });
        let pose = match &item.opposite_hand {
            Some(file) => {
                let file = resolve_file(&dir, file);
                write_opposite_hand(asm, &seed, &file)?;
                let t = seed.pose.translation;
                let translation = reflect(t - o, n) + o;
                let pose = Pose::new(translation, rot);
                let configuration = seed.configuration;
                let loaded = match asm.cache.part(&file, configuration) {
                    Ok(p) => Loaded::Part(p),
                    Err(e) => Loaded::Missing(e),
                };
                instances.push(Instance {
                    key: vec![key],
                    name: format!("{} (opposite hand)", seed.name),
                    pose,
                    loaded,
                    file,
                    configuration,
                    hidden: seed.hidden,
                    fixed: true,
                    exclude_from_bom: seed.exclude_from_bom,
                    derived: Some(m.id),
                });
                continue;
            }
            None => {
                let p_local = anchor(&seed, m.position);
                let world = seed.pose.point(p_local);
                let mirrored = reflect(world - o, n) + o;
                Pose::new(mirrored - rot * p_local, rot)
            }
        };
        let t = pose.then(&seed.pose.inverse());
        instances.extend(copies(base, &item.component, &key, &t, m.id, "(mirror)"));
    }
    Ok(Derived {
        id: m.id,
        instances,
    })
}

/// Write (or refresh) an opposite-hand part: the source part's features
/// followed by a whole-body mirror in its YZ plane that replaces the body.
fn write_opposite_hand(asm: &mut Assembly, seed: &Instance, file: &Path) -> Result<(), String> {
    let source = seed
        .part()
        .ok_or("only parts can have opposite-hand versions")?;
    let tag = format!("{}#{}", source.path.display(), source.hash);
    if let Ok(existing) = of_model::file::load(file)
        && existing
            .properties
            .get("OppositeHandOf")
            .is_some_and(|p| p.value == tag)
    {
        return Ok(());
    }
    let mut doc = of_model::file::load(&source.path)?;
    doc.rollback = None;
    let id = doc.add(FeatureKind::Mirror(MirrorDef {
        features: vec![],
        plane: Ref::RightPlane,
        keep_original: false,
    }));
    if let Some(f) = doc.feature_mut(id) {
        f.name = "Opposite hand".into();
    }
    doc.properties.insert(
        "OppositeHandOf".into(),
        of_model::properties::Property::text(tag),
    );
    of_model::file::save(&doc, file)?;
    asm.cache.forget(file);
    Ok(())
}
